insert into public.gear (slug, name, category, description, affiliate_url, recommended_for, sort_order)
values
  ('meater-plus', 'MEATER Plus Smart Thermometer', 'Thermometers', 'Wireless probe + app guides you through the brisket stall, alerts when meat is ready.', 'https://www.amazon.com.au/s?k=MEATER+Plus+Smart+Thermometer&tag=bsbsbs0f-22', null, 1),
  ('thermapen-one', 'ThermoWorks Thermapen ONE', 'Thermometers', '1-second ±0.3°C accuracy — perfect for spot-checking chicken, ribs, and brisket.', 'https://www.amazon.com.au/s?k=ThermoWorks+Therapen+ONE&tag=bsbsbs0f-22', null, 2),
  ('thermoworks-dot', 'ThermoWorks Dot Alarm Thermometer', 'Thermometers', 'Set-and-forget high/low temp alarms — ideal for monitoring long low-and-slow smokes.', 'https://www.amazon.com.au/s?k=ThermoWorks+Dot+Thermometer&tag=bsbsbs0f-22', null, 3),
  ('inkbird-ibt4xs', 'Inkbird IBT-4XS Bluetooth Thermometer', 'Thermometers', 'Dual-probe, app-controlled — monitors meat and smoker temp simultaneously.', 'https://www.amazon.com.au/s?k=Inkbird+IBT-4XS+Bluetooth+Thermometer&tag=bsbsbs0f-22', null, 4),
  ('grill-heat-aid-gloves', 'Grill Heat Aid Silicone Gloves', 'Safety & Protection', '800°C heat protection — grab hot brisket or ribs straight off the grate safely.', 'https://www.amazon.com.au/s?k=Grill+Heat+Aid+Silicone+Gloves&tag=bsbsbs0f-22', null, 5),
  ('grill-society-gloves', 'Grill Society Disposable BBQ Gloves', 'Safety & Protection', 'Nitrile + reusable liners — keeps hands clean when handling raw meat, no cross-contamination.', 'https://www.amazon.com.au/s?k=Grill+Society+Disposable+BBQ+Gloves&tag=bsbsbs0f-22', null, 6),
  ('wiltshire-bar-b-pack', 'Wiltshire BAR-B PACK Tool Set', 'Tools & Accessories', 'Spatula + tongs starter kit — essential for flipping and serving without bark damage.', 'https://www.amazon.com.au/s?k=Wiltshire+BAR-B+PACK+Tool+Set&tag=bsbsbs0f-22', null, 7),
  ('weber-16-tongs', 'Weber 16" Stainless Steel Tongs', 'Tools & Accessories', 'Long reach, locking mechanism — no bark damage when turning large cuts.', 'https://www.amazon.com.au/s?k=Weber+16+inch+Stainless+Steel+Tongs&tag=bsbsbs0f-22', null, 8),
  ('oxo-bbq-turner', 'OXO Good Grips BBQ Turner', 'Tools & Accessories', 'Wide, thin edge slides under brisket or fish without tearing — the lifter to own.', 'https://www.amazon.com.au/s?k=OXO+Good+Grips+BBQ+Turner&tag=bsbsbs0f-22', null, 9),
