  ('bbq-dragon-firebox', 'BBQ Dragon Firebox', 'Tools & Accessories', 'Perfect charcoal temp control — maintains steady 100–150°C for unattended long cooks.', 'https://www.amazon.com.au/s?k=BBQ+Dragon+Firebox&tag=bsbsbs0f-22', null, 12),
  ('bbq-guru-digiq', 'BBQ Guru DigiQ DX3 Thermostat Controller', 'Tools & Accessories', 'Sets and holds smoker temp automatically — ideal for overnight brisket cooks.', 'https://www.amazon.com.au/s?k=BBQ+Guru+DigiQ+DX3&tag=bsbsbs0f-22', null, 13),
